"""Stage target workers using pinned official tools; no worker is started."""
from pathlib import Path
import os,pwd,subprocess,base64
from dotenv import dotenv_values
ROOT=Path('/opt/m-ranked/releases/app-v30-20260907')
SCRIPTS=ROOT/'operations/scripts'
SCRIPTS.mkdir(parents=True,exist_ok=True)
FILES={'projection-publisher.sh': '', 'cache-outbox-worker.sh': '', 'run-maintenance.sh': ''}
for name,body in FILES.items():
 p=SCRIPTS/name;p.write_bytes(base64.b64decode(body));p.chmod(0o755)
build=ROOT/'worker-image';build.mkdir(exist_ok=True)
(build/'Dockerfile').write_text("""FROM redis:8.10.0@sha256:344e3945a0b431c8ff1eecd58c5573538126bd756f02fc7e218ddf1fc2546366 AS redis
FROM postgres:18.6@sha256:4ef4dbc939d61acea57712655ddb4b4ab27419c913f94cca0cd57cb3ea3c2280
COPY --from=redis /usr/local/bin/redis-cli /usr/local/bin/redis-cli
RUN redis-cli --version && psql --version
ENTRYPOINT []
""")
subprocess.run(['docker','build','--tag','mranked-target-workers:20260907',str(build)],check=True)
image=subprocess.check_output(['docker','image','inspect','mranked-target-workers:20260907','--format','{{.Id}}'],text=True).strip()
env=dotenv_values('/etc/m-ranked/infra/production.env')
for label,script,daemon in [('projection-publisher','projection-publisher.sh',True),('cache-outbox','cache-outbox-worker.sh',True),('maintenance','run-maintenance.sh',False)]:
 username='m-ranked-'+('projection' if label=='projection-publisher' else 'outbox' if label=='cache-outbox' else 'maintenance')
 try: user=pwd.getpwnam(username)
 except KeyError:
  subprocess.run(['useradd','--system','--no-create-home','--shell','/usr/sbin/nologin',username],check=True);user=pwd.getpwnam(username)
 private=Path('/etc/m-ranked')/(label+'-secrets');private.mkdir(mode=0o700,exist_ok=True);os.chown(private,user.pw_uid,user.pw_gid)
 escaped=env['MAINTENANCE_DB_PASSWORD'].replace('\\','\\\\').replace(':','\\:')
 secrets={'pgpass':'127.0.0.1:5432:mranked:maintenance:'+escaped+'\n','redis-password':env['REDIS_PASSWORD']}
 for name,value in secrets.items():
  p=private/name;p.write_text(value);p.chmod(0o400);os.chown(p,user.pw_uid,user.pw_gid)
 prefix={'projection-publisher':'PROJECTION','cache-outbox':'OUTBOX','maintenance':'MAINTENANCE'}[label]
 name='m-ranked-target-'+label
 extras='-e REDIS_PASSWORD_FILE=/run/secrets/redis-password' if label=='cache-outbox' else ''
 config=f"""[Unit]
Description=M-Ranked target {label}
Requires=docker.service
After=docker.service network-online.target
[Service]
Type={'simple' if daemon else 'oneshot'}
ExecStart=/usr/bin/docker run --rm --name {name} --network host --user {user.pw_uid}:{user.pw_gid} --read-only --cap-drop ALL --security-opt no-new-privileges:true --memory 96m --memory-swap 96m --cpus 0.15 --pids-limit 32 --log-opt max-size=10m --log-opt max-file=3 -v {SCRIPTS}:/scripts:ro -v {private}:/run/secrets:ro -e PGPASSFILE=/run/secrets/pgpass -e {prefix}_DATABASE_URL=postgresql://maintenance@127.0.0.1:5432/mranked {extras} {image} /bin/bash /scripts/{script}
ExecStop=/usr/bin/docker stop --timeout 20 {name}
TimeoutStopSec=30
TimeoutStartSec={'0' if daemon else '20min'}
Restart={'on-failure' if daemon else 'no'}
RestartSec=10
UMask=0077
[Install]
WantedBy=multi-user.target
"""
 if not daemon:
  config='\n'.join(line for line in config.splitlines() if not line.startswith('ExecStop='))+'\n'
 Path('/etc/systemd/system',name+'.service').write_text(config)
Path('/etc/systemd/system/m-ranked-target-maintenance.timer').write_text('[Unit]\nDescription=M-Ranked daily partition maintenance\n[Timer]\nOnCalendar=*-*-* 00:15:00 UTC\nPersistent=true\nRandomizedDelaySec=10min\n[Install]\nWantedBy=timers.target\n')
subprocess.run(['systemctl','daemon-reload'],check=True)
subprocess.run(['systemd-analyze','verify',*[str(Path('/etc/systemd/system')/('m-ranked-target-'+x+'.service')) for x in ('projection-publisher','cache-outbox','maintenance')]],check=True)
print('Workers staged and verified, not started.')
